export function logPageView(pagePath: string, userId?: string) {
  if (typeof process !== 'undefined' && process.env.NODE_ENV === 'development') {
    console.log(`[Analytics] Would log page view for: ${pagePath}`);
    return;
  }

  const analyticsPromise = fetch('https://api.analytics-service.com/pageview', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      path: pagePath,
      userId,
      timestamp: new Date().toISOString(),
      userAgent: 'server',
    }),
  }).catch(error => {
    console.error('Failed to log page view:', error);
  });

  return analyticsPromise;
}

